import{_ as a,o as r,c as n,ae as t}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Slack: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/slack.md","filePath":"adrs/1917971986/references/slack.md"}'),i={name:"adrs/1917971986/references/slack.md"};function o(s,e,l,c,h,p){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="slack-hierarchy-audiences-and-access" tabindex="-1">Slack: hierarchy, audiences, and access <a class="header-anchor" href="#slack-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Slack: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>Slack&#39;s enterprise product is still named Enterprise Grid in current documentation, and Slack&#39;s own pages use &quot;Enterprise Grid organization&quot; and &quot;Enterprise organization&quot; interchangeably for the top-level container, with help-center article titles themselves having shifted toward &quot;Enterprise organization&quot; while the product name &quot;Enterprise Grid&quot; remains in use (<a href="https://slack.com/help/articles/115002532808-Migrate-workspaces-to-an-Enterprise-organization" target="_blank" rel="noreferrer">Migrate workspaces to an Enterprise organization</a>; <a href="https://slack.com/resources/why-use-slack/slack-enterprise-grid" target="_blank" rel="noreferrer">An introduction to Slack Enterprise Grid</a>).</p><p>An Enterprise Grid organization is made up of an unlimited number of workspaces connected within that organization, often mapped to business units, departments, or subsidiaries (<a href="https://slack.com/resources/why-use-slack/slack-enterprise-grid" target="_blank" rel="noreferrer">An introduction to Slack Enterprise Grid</a>). Only Org Owners and Org Admins can create a new workspace in the organization; a member who cannot create one can instead request a new workspace for an owner or admin to review (<a href="https://slack.com/help/articles/115001344007-Create-a-workspace-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create a workspace on Enterprise Grid</a>). Below a workspace, channels are the unit that holds conversations, and a channel can be scoped to a single workspace, to several workspaces, or to every workspace in the organization; Slack does not document a further nesting level, such as folders, within this structure in the pages reviewed.</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>The organization is the governance layer: the Org Primary Owner is automatically assigned to every new workspace created in the organization, and organization-level settings are configured from organization settings rather than from any one workspace (<a href="https://slack.com/help/articles/115001344007-Create-a-workspace-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create a workspace on Enterprise Grid</a>). Work happens inside workspaces and their channels, not at the organization level itself.</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Slack channels have two base audiences. A public channel can be found, viewed, and joined by any member of the workspace, except guests, and its messages and files surface in workspace-wide search results for members. A private channel is for conversations that should not be open to everyone, people must be added by an existing member, and its messages and files only appear in search for people who are already in the channel (<a href="https://slack.com/help/articles/360017938993-Organize-your-work-in-channels" target="_blank" rel="noreferrer">What is a channel?</a>).</p><p>On Enterprise Grid, a channel&#39;s audience can be widened past a single workspace. A multi-workspace channel brings people from different workspaces together in the same channel, and Org Owners, Org Admins, and members with the right permission can add a channel to additional workspaces (<a href="https://slack.com/help/articles/115001399587-Create-multi-workspace-channels-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create multi-workspace channels on Enterprise Grid</a>). A multi-workspace channel that is added to every workspace in the organization and set as a default for new members becomes an org-wide default channel; an organization can have up to 25 such default channels (<a href="https://slack.com/help/articles/115001399587-Create-multi-workspace-channels-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create multi-workspace channels on Enterprise Grid</a>).</p><p>Guests are a narrower, named audience below ordinary members. A single-channel guest can access only the one channel they were invited to. A multi-channel guest can access only the channels specified for them, though they can additionally accept channel invitations and invite others into private channels they already belong to. Both guest types can see only the members and apps present in their own assigned channels, not the wider workspace or organization, and only Workspace Owners and Admins can manage a guest&#39;s channel access (<a href="https://slack.com/help/articles/202518103-Understand-guest-roles-in-Slack" target="_blank" rel="noreferrer">Understand guest roles in Slack</a>).</p><p>Slack Connect extends audience outward, to people outside the organization entirely. It lets a workspace collaborate with external organizations in a shared channel, hosting up to 250 organizations at once on paid plans, or in a direct message available on any plan; only the organization that owns a Slack Connect channel can invite or remove other organizations and manage posting permissions in it (<a href="https://slack.com/help/articles/115004151183-Slack-Connect-guide-Work-with-external-organizations" target="_blank" rel="noreferrer">Slack Connect guide: Work with external organizations</a>).</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>A workspace inside an Enterprise Grid organization can narrow who may even find or join it. Workspace owners choose among Open, meaning any org member can find and join; By request, meaning org members must ask to join; Invite only; or Hidden, meaning the workspace is not visible and people must be added directly (<a href="https://slack.com/help/articles/115001915507-Manage-workspace-access-on-Enterprise-Grid" target="_blank" rel="noreferrer">Manage workspace access on Enterprise Grid</a>). At the channel level, a private channel is the narrowing mechanism below a workspace&#39;s default openness: membership is granted only by an existing member adding someone, with no self-service request-to-join flow documented for private channels (<a href="https://slack.com/help/articles/205239967-Join-a-channel" target="_blank" rel="noreferrer">Join a channel</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Organization-level policies can cap what individual workspace owners and admins are allowed to configure, but Slack documents this as opt-in, not automatic. For app installation, &quot;setting an app management policy turns on app approval for every workspace in an org,&quot; while &quot;if you don&#39;t set an app management policy for your org, Workspace Owners can still choose to enable approval for workspaces they manage&quot; (<a href="https://slack.com/help/articles/360038559694-Set-organization-policies-for-apps-on-Enterprise-Grid" target="_blank" rel="noreferrer">Set organization policies for apps on Enterprise Grid</a>). Once such a policy is set, it can take away a workspace owner&#39;s discretion entirely, for example by removing workspace owners&#39; ability to manage &quot;Sign in with Slack&quot; permissions once the organization sets its own policy (<a href="https://slack.com/help/articles/360038559694-Set-organization-policies-for-apps-on-Enterprise-Grid" target="_blank" rel="noreferrer">Set organization policies for apps on Enterprise Grid</a>).</p><p>The same opt-in ceiling pattern applies to external collaboration. Organization admins choose, per invitation type, which roles in the organization may send Slack Connect channel invitations at all, which caps every workspace&#39;s ability to let its members invite external organizations (<a href="https://slack.com/help/articles/1500012572621-Manage-Slack-Connect-channel-invitation-settings-and-permissions" target="_blank" rel="noreferrer">Manage Slack Connect channel invitation settings and permissions</a>). Organization-level settings more broadly govern things like display name rules, retention, and channel posting permissions across every workspace in the organization, while workspace-level settings apply only to that one workspace (<a href="https://slack.com/help/articles/360038559694-Set-organization-policies-for-apps-on-Enterprise-Grid" target="_blank" rel="noreferrer">Set organization policies for apps on Enterprise Grid</a>).</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Private channels are the closed end of Slack&#39;s discovery spectrum: they are not found through browsing or search by people outside them, and the only documented path in is being added by an existing member, with no request-to-join option described (<a href="https://slack.com/help/articles/205239967-Join-a-channel" target="_blank" rel="noreferrer">Join a channel</a>; <a href="https://slack.com/help/articles/360017938993-Organize-your-work-in-channels" target="_blank" rel="noreferrer">What is a channel?</a>). At the workspace level, the By request access option is the open end of that spectrum: the workspace can be found by every org member, who can then ask to join rather than being invited outright (<a href="https://slack.com/help/articles/115001915507-Manage-workspace-access-on-Enterprise-Grid" target="_blank" rel="noreferrer">Manage workspace access on Enterprise Grid</a>). A member who cannot create a workspace can similarly request that a new one be created, rather than being blocked outright (<a href="https://slack.com/help/articles/115001344007-Create-a-workspace-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create a workspace on Enterprise Grid</a>).</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>Enterprise Grid is described as Slack&#39;s product for large or complex organizations that need multiple connected workspaces under one container; it is a distinct offering from the Free, Pro, and Business+ plans, which run as a single workspace with no organization layer above it (<a href="https://slack.com/resources/why-use-slack/slack-enterprise-grid" target="_blank" rel="noreferrer">An introduction to Slack Enterprise Grid</a>). A team on one of those plans operates only in its workspace and never encounters organization settings, organization policies, or an organization switcher, because that layer is part of a different product tier rather than something hidden within the same product.</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Slack documents bringing an existing workspace into an Enterprise organization as a migration, not an ordinary move. An Org Owner submits a migration request using the workspace&#39;s ID and URL, and the workspace&#39;s Primary Owner must approve or deny it before anything happens (<a href="https://slack.com/help/articles/115002532808-Migrate-workspaces-to-an-Enterprise-organization" target="_blank" rel="noreferrer">Migrate workspaces to an Enterprise organization</a>). Once approved, Slack walks the admins through a checklist covering SSO setup, matching identical user accounts, resolving conflicting accounts that share some but not all profile fields, and reviewing settings that differ between the workspace and the organization (<a href="https://slack.com/help/articles/115002532808-Migrate-workspaces-to-an-Enterprise-organization" target="_blank" rel="noreferrer">Migrate workspaces to an Enterprise organization</a>). After migration, members keep their channel and direct-message history, files, custom emoji, and apps, and direct messages across the merged workspaces are combined (<a href="https://slack.com/help/articles/115002532808-Migrate-workspaces-to-an-Enterprise-organization" target="_blank" rel="noreferrer">Migrate workspaces to an Enterprise organization</a>). Merging two separately created Enterprise organizations into one is not covered by this migration flow; the same help article directs that request to Slack&#39;s support team instead, so no self-service path for that case is documented.</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Slack&#39;s Enterprise Grid organization-to-workspace relationship is the clearest working example of this ADR&#39;s organization-governs, workspace-holds-work split: the Org Primary Owner is assigned at the organization level and organization settings apply across every workspace, while channels and conversations are the work that sits inside a workspace.</li><li>Slack&#39;s Free, Pro, and Business+ plans confirm the ADR&#39;s small-customer rule in its strongest form: a one-workspace team is not merely shielded from an organization screen, it is on a product tier that has no organization layer at all, which is a stricter version of this ADR&#39;s &quot;friendly by default&quot; reveal-on-growth design.</li><li>Slack private channels are the named source for this ADR&#39;s closed discovery example, and the research confirms it precisely: a private channel&#39;s existence is not surfaced to non-members through search or browsing, and the only documented way in is a direct add, with no request-to-join flow, unlike the workspace-level By request option, which leaves discovery open.</li><li>Slack&#39;s organization-level policies, such as app approval and Slack Connect invitation rules, are an opt-in ceiling an org admin must deliberately turn on, matching this ADR&#39;s rule that &quot;root ceilings are opt-in per policy&quot; rather than always-on.</li><li>Slack diverges from the ADR&#39;s &quot;project&quot; vocabulary: Slack has no resource positioned as a project attached to a workspace or folder, and it has no documented folder level between a workspace and its channels, so the ADR&#39;s folder and project layers have no direct Slack counterpart; and consolidating separate Enterprise organizations is explicitly left to Slack support rather than being a documented self-service migration, so the ADR&#39;s &quot;explicit cross-tenant migration&quot; expectation is confirmed for workspace-into-org moves but left unverified for org-into-org moves.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://slack.com/help/articles/115002532808-Migrate-workspaces-to-an-Enterprise-organization" target="_blank" rel="noreferrer">Migrate workspaces to an Enterprise organization</a></li><li><a href="https://slack.com/resources/why-use-slack/slack-enterprise-grid" target="_blank" rel="noreferrer">An introduction to Slack Enterprise Grid</a></li><li><a href="https://slack.com/help/articles/115001344007-Create-a-workspace-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create a workspace on Enterprise Grid</a></li><li><a href="https://slack.com/help/articles/115001915507-Manage-workspace-access-on-Enterprise-Grid" target="_blank" rel="noreferrer">Manage workspace access on Enterprise Grid</a></li><li><a href="https://slack.com/help/articles/202518103-Understand-guest-roles-in-Slack" target="_blank" rel="noreferrer">Understand guest roles in Slack</a></li><li><a href="https://slack.com/help/articles/205239967-Join-a-channel" target="_blank" rel="noreferrer">Join a channel</a></li><li><a href="https://slack.com/help/articles/360017938993-Organize-your-work-in-channels" target="_blank" rel="noreferrer">What is a channel? (Organize your work in channels)</a></li><li><a href="https://slack.com/help/articles/360038559694-Set-organization-policies-for-apps-on-Enterprise-Grid" target="_blank" rel="noreferrer">Set organization policies for apps on Enterprise Grid</a></li><li><a href="https://slack.com/help/articles/1500012572621-Manage-Slack-Connect-channel-invitation-settings-and-permissions" target="_blank" rel="noreferrer">Manage Slack Connect channel invitation settings and permissions</a></li><li><a href="https://slack.com/help/articles/115004151183-Slack-Connect-guide-Work-with-external-organizations" target="_blank" rel="noreferrer">Slack Connect guide: Work with external organizations</a></li><li><a href="https://slack.com/help/articles/115001399587-Create-multi-workspace-channels-on-Enterprise-Grid" target="_blank" rel="noreferrer">Create multi-workspace channels on Enterprise Grid</a></li></ul>',27)])])}const k=a(i,[["render",o]]);export{g as __pageData,k as default};
